from __future__ import annotations

# This module contains the generated first-generation LISA/Taiji TDI response
# functions used for the LISA-Taiji soft-memory PE example.  The four response
# functions below are mechanically extracted from examples/JAX_LISA-Taiji.ipynb,
# cell 3, from the analysis repository.  The surrounding setup code is compact
# and explicit so the public example does not need to execute a notebook.

from typing import Any

import jax
jax.config.update("jax_enable_x64", True)
import jax.numpy as jnp
import numpy as np

YR = 31558149.763545603
C_LIGHT = 3.0e8
L_LISA = 2.5e9
L_TAIJI = 3.0e9
R_AU = 149597870700.0
INNER_FMAX = 0.04

# Globals used by the generated response expressions.  They are initialized by
# configure() before any response evaluation in the public driver.
freq_noise = jnp.asarray(np.array([0.0, 1.0, 2.0]))
f = jnp.asarray(np.array([1.0]))
I = 1j
pi = jnp.pi
c = C_LIGHT
Llisa = L_LISA
Ltaiji = L_TAIJI
yr = YR
R = R_AU
exp = jnp.exp
cos = jnp.cos
sin = jnp.sin
sqrt = jnp.sqrt
e = jnp.e
eta = jnp.pi / 4.0
NAlisa = jnp.asarray(np.array([1.0]))
NAtaiji = jnp.asarray(np.array([1.0]))
tilde_noise_taiji_A = jnp.asarray(np.zeros(3, dtype=np.complex128))
tilde_noise_taiji_E = jnp.asarray(np.zeros(3, dtype=np.complex128))
tilde_noise_lisa_A = jnp.asarray(np.zeros(3, dtype=np.complex128))
tilde_noise_lisa_E = jnp.asarray(np.zeros(3, dtype=np.complex128))
T = 0.001 * YR


def _instrument_psd_np(freq: np.ndarray, *, detector: str) -> np.ndarray:
    freq = np.asarray(freq, dtype=float)
    if detector == "lisa":
        arm = L_LISA
        soms = (1.5e-11 * 2.0 * freq * np.pi / C_LIGHT) ** 2 * (1.0 + (2.0e-3 / freq) ** 4)
    elif detector == "taiji":
        arm = L_TAIJI
        soms = (0.8e-11 * 2.0 * freq * np.pi / C_LIGHT) ** 2 * (1.0 + (2.0e-3 / freq) ** 4)
    else:
        raise ValueError(f"unknown detector {detector!r}")
    sacc = (
        (3.0e-15 / (freq * 2.0 * np.pi * C_LIGHT)) ** 2
        * (1.0 + (0.4e-3 / freq) ** 2)
        * (1.0 + (freq / 8.0e-3) ** 4)
    )
    tau = 2.0 * np.pi * freq * arm / C_LIGHT
    return 8.0 * np.sin(tau) ** 2 * (
        2.0 * (3.0 + 2.0 * np.cos(tau) + np.cos(2.0 * tau)) * sacc
        + (2.0 + np.cos(tau)) * soms
    )


def _instrument_psd_jnp(freq: Any, *, detector: str):
    if detector == "lisa":
        arm = Llisa
        soms = (1.5e-11 * 2.0 * freq * jnp.pi / c) ** 2 * (1.0 + (2.0e-3 / freq) ** 4)
    elif detector == "taiji":
        arm = Ltaiji
        soms = (0.8e-11 * 2.0 * freq * jnp.pi / c) ** 2 * (1.0 + (2.0e-3 / freq) ** 4)
    else:
        raise ValueError(f"unknown detector {detector!r}")
    sacc = (
        (3.0e-15 / (freq * 2.0 * jnp.pi * c)) ** 2
        * (1.0 + (0.4e-3 / freq) ** 2)
        * (1.0 + (freq / 8.0e-3) ** 4)
    )
    tau = 2.0 * jnp.pi * freq * arm / c
    return 8.0 * jnp.sin(tau) ** 2 * (
        2.0 * (3.0 + 2.0 * jnp.cos(tau) + jnp.cos(2.0 * tau)) * sacc
        + (2.0 + jnp.cos(tau)) * soms
    )


def _noise_from_psd(length: int, delta_t: float, psd: np.ndarray, delta_f: float, *, seed: int) -> np.ndarray:
    try:
        import pycbc.noise
        from pycbc.types import FrequencySeries
    except Exception as exc:  # pragma: no cover - exercised only without optional dependency
        raise RuntimeError("PyCBC is required to generate the public example noise realization") from exc
    series = FrequencySeries(psd, delta_f=delta_f)
    return np.asarray(pycbc.noise.noise_from_psd(length, delta_t, series, seed=seed))


def configure(
    *,
    sampling_frequency_hz: float = 1.0,
    duration_yr: float = 1.0e-3,
    eta_value: float = float(np.pi / 4.0),
    noise_seeds: tuple[int, int, int, int] = (123, 124, 125, 126),
) -> dict[str, Any]:
    global freq_noise, f, T, eta, NAlisa, NAtaiji
    global tilde_noise_taiji_A, tilde_noise_taiji_E, tilde_noise_lisa_A, tilde_noise_lisa_E

    T = float(duration_yr) * YR
    eta = jnp.asarray(eta_value)
    delta_t = 1.0 / float(sampling_frequency_hz)
    tsamples = int(T / delta_t)
    time = np.arange(0, tsamples, dtype=float) * delta_t
    freq_psd = np.linspace(1.0e-5, float(sampling_frequency_hz), 5000)
    delta_f_psd = float(freq_psd[1] - freq_psd[0])
    psd_taiji = _instrument_psd_np(freq_psd, detector="taiji")
    psd_lisa = _instrument_psd_np(freq_psd, detector="lisa")

    noise_taiji_A = _noise_from_psd(tsamples, delta_t, psd_taiji, delta_f_psd, seed=int(noise_seeds[0]))
    noise_lisa_A = _noise_from_psd(tsamples, delta_t, psd_lisa, delta_f_psd, seed=int(noise_seeds[1]))
    noise_taiji_E = _noise_from_psd(tsamples, delta_t, psd_taiji, delta_f_psd, seed=int(noise_seeds[2]))
    noise_lisa_E = _noise_from_psd(tsamples, delta_t, psd_lisa, delta_f_psd, seed=int(noise_seeds[3]))

    tilde_noise_taiji_A = jnp.asarray(np.fft.rfft(noise_taiji_A) * delta_t)
    tilde_noise_lisa_A = jnp.asarray(np.fft.rfft(noise_lisa_A) * delta_t)
    tilde_noise_taiji_E = jnp.asarray(np.fft.rfft(noise_taiji_E) * delta_t)
    tilde_noise_lisa_E = jnp.asarray(np.fft.rfft(noise_lisa_E) * delta_t)
    freq_noise = jnp.asarray(np.fft.rfftfreq(len(time), delta_t))
    f = jnp.asarray(freq_noise[1:-1])
    NAlisa = _instrument_psd_jnp(f, detector="lisa")
    NAtaiji = _instrument_psd_jnp(f, detector="taiji")
    return get_context()


