@jax.jit
def innerA1taiji(h1, h2, Freq):
    df = Freq[1] - Freq[0]
    mask = Freq < INNER_FMAX
    integrand = 4.0 * jnp.real(jnp.conj(h1) * h2) / NAtaiji
    return df * jnp.sum(jnp.where(mask, integrand, 0.0))


@jax.jit
def innerA1lisa(h1, h2, Freq):
    df = Freq[1] - Freq[0]
    mask = Freq < INNER_FMAX
    integrand = 4.0 * jnp.real(jnp.conj(h1) * h2) / NAlisa
    return df * jnp.sum(jnp.where(mask, integrand, 0.0))


def get_context() -> dict[str, Any]:
    return {
        "f": f,
        "T": T,
        "freq_noise": freq_noise,
        "tilde_noise_taiji_A": tilde_noise_taiji_A,
        "tilde_noise_taiji_E": tilde_noise_taiji_E,
        "tilde_noise_lisa_A": tilde_noise_lisa_A,
        "tilde_noise_lisa_E": tilde_noise_lisa_E,
        "A1lisa": A1lisa,
        "E1lisa": E1lisa,
        "A1taiji": A1taiji,
        "E1taiji": E1taiji,
        "innerA1lisa": innerA1lisa,
        "innerA1taiji": innerA1taiji,
        "NAlisa": NAlisa,
        "NAtaiji": NAtaiji,
        "sampling_duration_s": T,
        "inner_fmax_hz": INNER_FMAX,
        "eta": eta,
    }
